449	            g.helper_total_lanes,
450	        ),
451	    ] {
452	        if a != e {
453	            return Err(format!("length mismatch in {s}: expected {e}, got {a}"));
454	        }
455	    }
456	    if inputs.pre_meta.len() < 3
457	        || inputs.pre_meta.len() != inputs.post_meta.len()
458	        || inputs.pre_prog.len() != inputs.post_prog.len()
459	        || inputs.meta_bounds_frames_offset >= inputs.pre_meta.len()
