575	        em.gated_validate_frame(ga, &pre_i[base..base + FRAME_LANES], p);
576	        let inactive = em.not(active);
577	        let gi = em.and(en.clone(), inactive);
578	        let hit = em.teq(Em::imm(slot as u128 + 1), depth.clone());
579	        for lane in 0..FRAME_LANES {
580	            em.gzero(gi.clone(), pre_i[base + lane].clone());
581	            top[lane] = em.sel(hit.clone(), pre_i[base + lane].clone(), top[lane].clone());
582	        }
583	    }
584	    top
585	}
