753	/// Applied (non-P3) helper charge: remaining work - 1, consumed work + 1,
754	/// helper work + 1, helper visits + `visits`; outcome and reference cursor
755	/// stay. The P3 helper-work refusal (`pre.helper_work == max_helper_work`) is
756	/// a different disposition and is rejected here, not constrained.
757	pub(super) fn charge_helper(em: &mut Em, inputs: &C6StepInputs, visits: u128) {
758	    use mori_core::sherlock::helper_machine::c6_phys::{L_HELPER_VISITS, L_HELPER_WORK};
759	    let en = inputs.enable.clone();
760	    let pre_i = &inputs.pre_image;
761	    let post_i = &inputs.post_image;
762	    let max_hw = inputs.source_params.admission_bounds().max_helper_work;
763	    let is_p3 = em.teq(pre_i[L_HELPER_WORK].clone(), Em::imm(max_hw));
764	    let not_p3 = em.not(is_p3);
765	    em.gassert(en.clone(), not_p3);
766	    let dec = em.add(post_i[L_REMAINING_WORK].clone(), Em::imm(1));
767	    em.geq(en.clone(), dec, pre_i[L_REMAINING_WORK].clone());
768	    for (lane, by) in [
769	        (L_CONSUMED_WORK, 1),
770	        (L_HELPER_WORK, 1),
771	        (L_HELPER_VISITS, visits),
772	    ] {
773	        if by > 0 {
774	            let room = em.lt128(pre_i[lane].clone(), Em::imm(u128::MAX - by + 1));
775	            em.gassert(en.clone(), room);
776	        }
777	        let inc = em.add(pre_i[lane].clone(), Em::imm(by));
778	        em.geq(en.clone(), post_i[lane].clone(), inc);
779	    }
780	}
